
import json
from pathlib import Path

from .rag import retrieve
from .generator import generate_answer


PROJECT_DIR = Path(__file__).resolve().parent.parent

QUESTIONS_PATH = (
    PROJECT_DIR / "data" / "evaluation" / "questions.json"
)

RESULTS_DIR = PROJECT_DIR / "results"


def load_questions():
    """Load evaluation questions."""

    with QUESTIONS_PATH.open("r", encoding="utf-8") as file:
        return json.load(file)


def evaluate_answers(top_k=4):
    """Evaluate answers generated by the language model."""

    questions = load_questions()
    results = []

    for index, item in enumerate(questions, start=1):

        question = item["question"]
        expected_answer = item["expected_answer"]

        expected_keywords = [
            keyword.lower()
            for keyword in item["expected_keywords"]
        ]

        print(f"\nEvaluating question {index}/{len(questions)}")
        print("Question:", question)

        retrieved_documents = retrieve(
            question,
            top_k=top_k
        )

        try:
            generation_result = generate_answer(
                question,
                retrieved_documents
            )

            answer = generation_result["answer"]

            answer_lower = answer.lower()

            matched_keywords = [
                keyword
                for keyword in expected_keywords
                if keyword in answer_lower
            ]

            keyword_recall = (
                len(matched_keywords) / len(expected_keywords)
                if expected_keywords
                else 0.0
            )

            results.append({
                "question": question,
                "expected_answer": expected_answer,
                "generated_answer": answer,
                "retrieved_documents": retrieved_documents,
                "matched_keywords": matched_keywords,
                "answer_keyword_recall": round(
                    keyword_recall, 3
                ),
                "model_status": generation_result["model_status"],
                "model": generation_result["model"],
            })

            print("Generated answer:", answer)
            print(
                "Answer keyword recall:",
                round(keyword_recall, 3)
            )

        except RuntimeError as error:

            print("Generation failed:", error)

            results.append({
                "question": question,
                "expected_answer": expected_answer,
                "generated_answer": None,
                "retrieved_documents": retrieved_documents,
                "matched_keywords": [],
                "answer_keyword_recall": 0.0,
                "model_status": "error",
                "error": str(error),
            })

    successful_results = [
        item for item in results
        if item["model_status"] == "connected"
    ]

    average_recall = (
        sum(
            item["answer_keyword_recall"]
            for item in successful_results
        ) / len(successful_results)
        if successful_results
        else 0.0
    )

    return {
        "number_of_questions": len(results),
        "successful_generations": len(successful_results),
        "failed_generations": (
            len(results) - len(successful_results)
        ),
        "average_answer_keyword_recall": round(
            average_recall, 3
        ),
        "details": results,
    }


def save_results(evaluation_results):
    """Save answer evaluation results as JSON."""

    RESULTS_DIR.mkdir(parents=True, exist_ok=True)

    output_path = RESULTS_DIR / "answer_evaluation.json"

    with output_path.open("w", encoding="utf-8") as file:
        json.dump(
            evaluation_results,
            file,
            indent=2,
            ensure_ascii=False,
        )

    return output_path


if __name__ == "__main__":

    evaluation_results = evaluate_answers(top_k=4)

    output_path = save_results(evaluation_results)

    print("\n" + "=" * 45)
    print("Answer evaluation completed.")
    print(
        "Successful generations:",
        evaluation_results["successful_generations"]
    )
    print(
        "Failed generations:",
        evaluation_results["failed_generations"]
    )
    print(
        "Average answer keyword recall:",
        evaluation_results["average_answer_keyword_recall"]
    )
    print("Results saved to:", output_path)
